    duplicate_range: TextRange,
    first_range: TextRange,
    normalized_list: String,
}

impl Rule for NoDuplicateSelectors {
    type Query = Semantic<AnyCssRoot>;
    type State = DuplicateSelectorList;
    type Signals = Box<[Self::State]>;
    type Options = NoDuplicateSelectorsOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let model = ctx.model();       // semantic model
        let root = ctx.root();
        // ... iterative DFS over model.rules(), rule.selectors(), s.resolved().normalize() ...
    }

    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(rule_category!(), state.duplicate_range,
                markup! { "Duplicate selector list \""<Emphasis>{state.normalized_list.as_str()}</Emphasis>"\"." })
            .detail(state.first_range, markup! { "It was first defined here." })
            .note(markup! { "Remove or merge the duplicate rule to keep the stylesheet clean." }),
        )
    }
}
```

This one uses the **semantic model** (`Semantic<AnyCssRoot>`, `ctx.model()`) which fully resolves nesting. If your rule only needs the raw CST (no nesting resolution), query a specific node directly instead — e.g. `no_unmatchable_anb_selector.rs` uses `type Query = Ast<CssPseudoClassNthSelector>;` and `no_unknown_type_selector.rs` uses `Ast<CssTypeSelector>`. Note `Semantic<T>` requires the `crate::services::semantic::Semantic` import; `Ast<T>` comes from `biome_analyze`.

For syntactic per-node rules, other useful patterns:
- `Ast<CssColor>` (no_hex_colors.rs:59)
- `Ast<CssPseudoElementSelector>` (no_unknown_pseudo_element.rs:87)
- `AnyPseudoLike` via `declare_node_union!` (no_unknown_pseudo_class.rs) — several CSS rules use `declare_node_union!` to query multiple node types with one rule.

