enum SelectorNode {
    Selector(AnyCssSelector),
}

impl SelectorNode {
    fn syntax(&self) -> &CssSyntaxNode {
        match self {
            Self::Selector(selector) => selector.syntax(),
        }
    }

    fn range(&self) -> TextRange {
        match self {
            Self::Selector(selector) => selector.range(),
        }
    }
}

/// Counts the number of class selectors within a selector subtree. Class
/// selectors nested inside pseudo-class function arguments (`:not()`, `:is()`,
/// `:has()`, `:nth-child(... of ...)`, etc.) are descendants of the selector and
/// are therefore counted as well.
fn count_class_selectors(syntax: &CssSyntaxNode) -> usize {
    syntax
        .descendants()
        .filter(|node| node.kind() == CssSyntaxKind::CSS_CLASS_SELECTOR)
        .count()
}

/// Returns `true` if the selector subtree contains an SCSS interpolation.
fn contains_interpolation(syntax: &CssSyntaxNode) -> bool {
    syntax
        .descendants()
        .any(|node| node.kind() == CssSyntaxKind::SCSS_INTERPOLATION)
}
